1. import { expect, test, type Page } from "@playwright/test";
2. import { clickLayoutItem } from "./helpers/layout";
3. 
4. const SAVE_KEY = "2dnd_save";
5. const MAIN_QUEST_ID = "twelvefoldCovenant";
6. const EPILOGUE_ID = "campaign.twelvefoldCovenant.epilogue";
7. const GAME_WIDTH = 640;
8. const GAME_HEIGHT = 528;
9. 
10. interface BrowserQuestProgress {
11.   status: string;
12.   stage: number;
13.   claimedRewards: string[];
14. }
15. 
16. interface BrowserSave {
17.   player: {
18.     name: string;
19.     inventory: Array<{ id: string }>;
20.     progression: {
21.       seenCutsceneIds: string[];
22.       pendingCutsceneIds: string[];
23.       pendingFeatureRevealIds?: string[];
24.       tutorial: {
25.         completed: boolean;
26.       };
27.       quests: {
28.         quests: Record<string, BrowserQuestProgress>;
29.       };
30.       achievements: {
31.         pendingNotificationIds: string[];
32.       };
33.     };
34.   };
35.   defeatedBosses: string[];
36. }
37. 
38. async function holdKey(
39.   page: Page,
40.   key: string,
41.   duration = 180,
42. ): Promise<void> {
43.   await page.keyboard.down(key);
44.   await page.waitForTimeout(duration);
45.   await page.keyboard.up(key);
46.   await page.waitForTimeout(120);
47. }
48. 
49. async function clickGame(
50.   page: Page,
51.   gameX: number,
52.   gameY: number,
53. ): Promise<void> {
54.   const canvas = page.locator("#game-container canvas");
55.   await expect(canvas).toBeVisible();
56.   const bounds = await canvas.boundingBox();
57.   if (!bounds) throw new Error("Game canvas has no rendered bounds");
58.   await page.mouse.click(
59.     bounds.x + (gameX / GAME_WIDTH) * bounds.width,
60.     bounds.y + (gameY / GAME_HEIGHT) * bounds.height,
61.   );
62. }
63. 
64. async function waitForState(page: Page, text: string): Promise<void> {
65.   await expect(page.locator("#debug-state")).toContainText(text);
66. }
67. 
68. async function enableDebug(page: Page): Promise<void> {
69.   const checkbox = page.locator("#debug-checkbox");
70.   if (!await checkbox.isChecked()) await checkbox.check();
71.   await expect(page.locator("#debug-panel")).toBeVisible();
72. }
73. 
74. async function submitDebug(page: Page, command: string): Promise<void> {
75.   const input = page.locator("#debug-cmd");
76.   await input.fill(command);
77.   await input.press("Enter");
78.   await input.blur();
79. }
80. 
81. async function readSave(page: Page): Promise<BrowserSave> {
82.   return page.evaluate((saveKey) => {
83.     const raw = localStorage.getItem(saveKey);
84.     if (!raw) throw new Error(`Missing localStorage save: ${saveKey}`);
85.     return JSON.parse(raw) as BrowserSave;
86.   }, SAVE_KEY);
87. }
88. 
89. async function advanceQuestDialogue(page: Page): Promise<void> {
90.   await holdKey(page, "Space");
91.   await holdKey(page, "Space");
92.   await holdKey(page, "Space");
93. }
94. 
95. async function enterCurrentTown(
96.   page: Page,
97.   expectedCityState: string,
98. ): Promise<void> {
99.   for (let attempt = 0; attempt < 5; attempt += 1) {
100.     await holdKey(page, "Space", 300);
101.     const state = await page.locator("#debug-state").textContent() ?? "";
102.     if (state.includes(expectedCityState)) return;
103.   }
104.   throw new Error(`Timed out entering town: ${expectedCityState}`);
105. }
106. 
107. async function advanceGenericCutscene(page: Page): Promise<void> {
108.   await page.waitForTimeout(420);
109.   await holdKey(page, "Enter");
110.   await page.waitForTimeout(420);
111. }
112. 
113. async function drainGenericCutscenesUntil(
114.   page: Page,
115.   destination: string,
116. ): Promise<void> {
117.   for (let attempt = 0; attempt < 30; attempt += 1) {
118.     const state = await page.locator("#debug-state").textContent() ?? "";
119.     if (state.includes(destination)) return;
120.     if (state.includes("CUTSCENE")) {
121.       await advanceGenericCutscene(page);
122.     } else {
123.       await page.waitForTimeout(150);
124.     }
125.   }
126.   throw new Error(`Timed out draining cutscenes to ${destination}`);
127. }
128. 
129. test("campaign golden path reaches and recovers the post-game ending", async ({
130.   page,
131. }) => {
132.   const browserErrors: string[] = [];
133.   page.on("pageerror", (error) => browserErrors.push(error.message));
134.   page.on("console", (message) => {
135.     if (message.type() === "error") browserErrors.push(message.text());
136.   });
137.   await page.addInitScript(() => {
138.     let seed = 0x2d0d2026;
139.     Math.random = () => {
140.       seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
141.       return seed / 0x1_0000_0000;
142.     };
143.     if (!sessionStorage.getItem("campaignGoldenPathInitialized")) {
144.       localStorage.clear();
145.       sessionStorage.setItem("campaignGoldenPathInitialized", "true");
146.     }
147.   });
148. 
149.   await test.step("create a new character", async () => {
150.     await page.goto("./", { waitUntil: "networkidle" });
151.     await waitForState(page, "BOOT | Screen: title");
152.     await clickGame(page, 320, 324);
153.     await waitForState(page, "BOOT | Screen: character");
154. 
155.     await clickGame(page, 320, 76);
156.     const nameInput = page.locator("#mobile-text-input input");
157.     await expect(nameInput).toBeVisible();
158.     await nameInput.fill("browserhero");
159.     await nameInput.press("Enter");
160.     await clickGame(page, 284, 160);
161.     await holdKey(page, "Enter");
162.     await waitForState(page, "BOOT | Screen: stats");
163. 
164.     await clickGame(page, 390, 64);
165.     await clickGame(page, 400, 460);
166.     await waitForState(page, "BOOT | Screen: appearance");
167.     await clickGame(page, 320, 112);
168.     await clickGame(page, 420, 312);
169.     await waitForState(page, "CUTSCENE | campaign.opening | Step 1/2");
170.     const interruptedSave = await readSave(page);
171.     expect(interruptedSave.player.progression.pendingCutsceneIds).toEqual([
172.       "campaign.opening",
173.       "campaign.stage.firstSeal",
