+    `| Boot texture generation | ${empty.bootTexturesMs.median} ms | `
+    + `${empty.bootTexturesMs.p95} ms | ${saved.bootTexturesMs.median} ms | `
+    + `${saved.bootTexturesMs.p95} ms |`,
+  );
