+    + `${result.save.combinedWriteMs.median} ms median / `
+    + `${result.save.combinedWriteMs.p95} ms p95.`,
+  );
+  console.log("\nBaseline JSON:");
+  console.log(JSON.stringify(result, null, 2));
+}
