43. function percentile(values, percentileValue) {
44.   if (values.length === 0) {
45.     throw new Error("Cannot summarize an empty metric sample");
46.   }
47.   const sorted = [...values].sort((left, right) => left - right);
48.   const index = Math.ceil(percentileValue * sorted.length) - 1;
