       "Missing npm_execpath; run the harness through "
       + "`npm run benchmark:baseline`.",
     );
   }
   const initialProvenance = await getGitProvenance();
   await runCommand(process.execPath, [npmCli, "run", "build"], {
     env: {
       ...process.env,
       VITE_BASE_PATH: BASE_PATH,
     },
   });

