9. import { BootScene } from "../src/scenes/Boot";
10. import { createCodex } from "../src/systems/codex";
11. import { createPlayer, type PlayerState } from "../src/systems/player";
12. import { deleteSave, loadGame, saveGame } from "../src/systems/save";
13. import { createWeatherState } from "../src/systems/weather";
14. 
15. interface TransitionManagerHarness {
16.   isPending: boolean;
17.   startWithFade(
18.     startScene: () => void,
19.     options: { duration?: number; label?: string },
20.   ): boolean;
21. }
22. 
23. interface BootTransitionHarness {
24.   continueGame(): void;
25.   startNewGame(player: PlayerState): void;
26.   sceneTransitions: TransitionManagerHarness;
27.   scene: { start(sceneKey: string, data?: unknown): void };
28. }
29. 
30. function createTestPlayer(name: string): PlayerState {
31.   return createPlayer(name, {
32.     strength: 10,
33.     dexterity: 10,
34.     constitution: 10,
35.     intelligence: 10,
36.     wisdom: 10,
37.     charisma: 10,
38.   });
39. }
40. 
41. describe("BootScene Overworld transition", () => {
42.   beforeEach(() => {
43.     deleteSave();
44.   });
45. 
46.   it("loads and starts Overworld with the complete persistent payload", () => {
47.     const player = createTestPlayer("LoadedHero");
48.     const defeatedBosses = new Set(["cryptLich"]);
49.     const codex = createCodex();
50.     const weatherState = createWeatherState();
51.     weatherState.stepsUntilChange = 17;
52.     saveGame(player, defeatedBosses, codex, player.appearanceId, 143, weatherState);
53. 
54.     const boot = new BootScene();
55.     const harness = boot as unknown as BootTransitionHarness;
56.     const start = vi.fn();
57.     let fadeComplete: (() => void) | undefined;
58.     const sceneTransitions: TransitionManagerHarness = {
59.       isPending: false,
60.       startWithFade: vi.fn((callback, options) => {
61.         expect(options).toEqual({
62.           duration: 500,
63.           label: "continue game",
64.         });
65.         fadeComplete = callback;
66.         sceneTransitions.isPending = true;
67.         return true;
68.       }),
69.     };
70.     Object.assign(harness, { sceneTransitions });
71.     Object.defineProperty(boot, "scene", {
72.       configurable: true,
73.       value: { start },
74.     });
75. 
76.     harness.continueGame();
77. 
78.     expect(start).not.toHaveBeenCalled();
79.     fadeComplete?.();
80. 
81.     const loaded = loadGame();
82.     expect(loaded).not.toBeNull();
83.     expect(start).toHaveBeenCalledWith("OverworldScene", {
84.       player: loaded!.player,
85.       defeatedBosses: new Set(["cryptLich"]),
86.       codex: loaded!.codex,
87.       timeStep: 143,
88.       weatherState: loaded!.weatherState,
89.       savedSpecialNpcs: [],
90.     });
91.   });
92. 
93.   it("starts a new campaign with fresh shared state instead of stale scene defaults", () => {
94.     const oldPlayer = createTestPlayer("OldHero");
95.     saveGame(
96.       oldPlayer,
97.       new Set(["infernoForgemaster"]),
98.       createCodex(),
99.       oldPlayer.appearanceId,
100.       300,
101.       createWeatherState(),
102.     );
103.     const player = createTestPlayer("NewHero");
104.     const boot = new BootScene();
105.     const harness = boot as unknown as BootTransitionHarness;
106.     const start = vi.fn();
107.     let fadeComplete: (() => void) | undefined;
108.     const sceneTransitions: TransitionManagerHarness = {
109.       isPending: false,
110.       startWithFade: vi.fn((callback, options) => {
111.         expect(options).toEqual({
112.           duration: 500,
113.           label: "start new game",
114.         });
115.         fadeComplete = callback;
116.         sceneTransitions.isPending = true;
117.         return true;
118.       }),
119.     };
120.     Object.assign(harness, { sceneTransitions });
121.     Object.defineProperty(boot, "scene", {
122.       configurable: true,
123.       value: { start },
124.     });
125. 
126.     harness.startNewGame(player);
127.     harness.startNewGame(player);
128. 
129.     const saved = loadGame();
130.     expect(saved).not.toBeNull();
131.     expect(saved!.player.name).toBe("NewHero");
132.     expect(saved!.defeatedBosses).toEqual([]);
133.     expect(saved!.timeStep).toBe(0);
134.     expect(saved!.player.progression.pendingCutsceneIds).toEqual([
135.       "campaign.opening",
136.       "campaign.stage.firstSeal",
137.     ]);
138.     expect(sceneTransitions.startWithFade).toHaveBeenCalledTimes(1);
139.     fadeComplete?.();
140. 
141.     expect(start).toHaveBeenCalledTimes(1);
142.     expect(start).toHaveBeenCalledWith("CutsceneScene", {
143.       player,
144.       defeatedBosses: new Set(),
145.       codex: { entries: {}, unlockedEntryIds: [] },
146.       timeStep: 0,
147.       weatherState: createWeatherState(),
148.       savedSpecialNpcs: [],
149.       cutsceneId: "campaign.opening",
150.       replay: false,
151.     });
152.   });
153. });
